INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8357ac3e-e4c8-5508-8a73-93f74cff3564','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BİROĞLU İNŞAAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'e251c77c-b71d-55c5-99b4-c0039b9ac56d'::uuid),'44ec101f-9797-407c-8a29-1d0bb1317339','Uğur Yıldız','TICARI','TAMAMLANDI','2026-04-27','Uğur YILDIZ','satıalma sorumlusu hülya kaya hanım ile ankara çankaya merkez ofislerinde görüşüldü hülya hanım ön satın alma biriminde olduğunu ve firmanın Diyarbakır Şırnak Mardin illerinde yol işi yaptığını şu an ise sadece Diyarbakır şantiyelerinde işlerinin devam ettiğini ve bu şantiyeden zaman zaman lastik talebinin geldiğini alım esnasında şantiyede bulunan Özgür Bey''in daha çok Alima müdahil olduğunu söyledi Özgür Bey''in iletişim bilgileri alındı kendisi ile görüşüldü Abdulkadir Özcan ile Petlas Marc''a alım yaptıklarına fakat Lassa için ihtiyaç durumunla tarafımızdan mutlaka fiyat alacağını söyledi 23.526 26.526 için Orbit kaplama fiyat teklifini yakın zamanda tarafımızdan alacağını söyledi kendisinin zaman zaman Ankara merkez ofisine geldiğini geldiği zaman da haber verip görüşmemi istedi bu firmada sürekli iletişim ve yakın takip halinde bulunacagim','{}'::jsonb,'EXCEL_MIGRASYON','44ec101f-9797-407c-8a29-1d0bb1317339') ON CONFLICT (id) DO NOTHING;
