INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8c68ec48-edcf-5dd7-9f87-54ddbf2ffcf0','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KURU GÖLLÜ İNŞAAT' AND il IS NOT DISTINCT FROM 'SİVAS' LIMIT 1),'9d500d0c-9325-5993-9a6d-d2bf1916b7c4'::uuid),'44ec101f-9797-407c-8a29-1d0bb1317339','Uğur Yıldız','TICARI','TAMAMLANDI','2026-04-28','Uğur YILDIZ','Şirket sahibi Fatih bey ile Ankara OSTİM''de görüşüldü şirketin Bolu göynük harfiyat nakliye işi bittiğini söyledi Sivas Kandal''daki harfiyat işlerinin bir kısmının devam ettiğini bunun yanı sıra Antalya Manavgatgat''ta hazır beton tesisi satın aldıklarını ve hazır beton tesisinde toplam 20 adet mikser iki adet lastikli iş makinası çalıştığını söyledi bu firma ile geçen dönemlerde toplam üç sefer Ticaretimiz oldu ve özellikle satın almış oldukları lastik Lassa marka nadiren Pirelli alımı da yapıyor firma 90 günlük check ile lastik alımı gerçekleştiriyor kullanmış oldukları lastik ölçüsü hafriyatta çalışan kamyonlarda 13 R 22:5 mikserlerde kullandığı lastik ölçüleri ise 315 80 R 22.5 genelde fiyat odaklı 3 4 yerden lastik fiyat teklifi alıp en ucuz teklif üzerinden alım yapan bir nokta tekraren bir süreci hakkında Fatih Bey''e bilgi verildi ilk lastik ihtiyacında tarafımızdan fiyat teklifi isteyeceğini söyledi','{}'::jsonb,'EXCEL_MIGRASYON','44ec101f-9797-407c-8a29-1d0bb1317339') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('0ed36dcd-6e5f-5305-a262-b3a4e730ead3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YÜCELEN GRUP' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'2745cb05-4c8a-5431-b2ac-5ad9f227c59e'::uuid),'44ec101f-9797-407c-8a29-1d0bb1317339','Uğur Yıldız','TICARI','TAMAMLANDI','2026-04-28','Uğur YILDIZ','Satın alma sorumlusu Abdullah Bey''le görüşüldü bu filo ile yaklaşık beş yıldır Ticaretimiz var Ankara merkezli bir şirket aynı zamanda İstanbul tarafında uluslararası taşımacılık yapan 26 adet çekici 30 adet Dorsesi olan ve İstanbul Avrupa yakasında garajı bulunan firmalardan bir tanesi gerek yeni lastik gerek ise kaplama tarafında Ticaretimiz halen devam ediyor Brisa süreci hakkında Abdullah Bey''e bilgi verdim özellikle Ankara''da gıda firmalarında kiralık olarak çalıştırmış oldukları 80 civarında Ford transit Marc''a araçları var bundan sonraki lastik ihtiyaçların da Lassa marka tercih etmiş oldukları lastikler için mutlaka fiyat teklifini alacaklarini söylediler','{}'::jsonb,'EXCEL_MIGRASYON','44ec101f-9797-407c-8a29-1d0bb1317339') ON CONFLICT (id) DO NOTHING;
