INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('4cfb87e4-32a5-5897-bda1-7b26e8528ebf','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SUPET ULUSLARARASI NAKLİYAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'1a4eea87-48d3-5998-bf3f-1090f1cc3b4b'::uuid),'44ec101f-9797-407c-8a29-1d0bb1317339','Uğur Yıldız','TICARI','TAMAMLANDI','2026-04-29','Uğur YILDIZ','Şirket sahibi metin bey ile Ankara şaşmaz merkez ofislerinde görüşüldü geçen yıllarda ihtiyaç durumlarında Continental Marc''a 315 70 R 22.5 düz çeker ve 385 55 R 22.5 385 65 R 22.5 lastik Ticaretimiz olmuştu metin bey son gelen zamlardan dolayı ihtiyaç durumunda yaşar oto lastik ile Pirelli Marc''a lastik alımı yaptıklarını söyledi kendisine Brisa süreci hakkında bilgi verildi bundan sonraki  ihtiyaç durumunda fiyat alacağını söyledi bu filoda toplam 28 adet çekici 30 adet Dorse mevcut uluslararası taşımacılık yaptığı bölge Rusya ağırlıkla Ankara''nın yaklaşık 35 yıllık firmalarından bir tanesi','{}'::jsonb,'EXCEL_MIGRASYON','44ec101f-9797-407c-8a29-1d0bb1317339') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('cde6939b-0a0e-50ae-8ff4-ddfdcf8f121d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İLHAN KARDEŞLER VINÇ' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'5e780356-776a-5ebd-88a9-2661d6af91a7'::uuid),'44ec101f-9797-407c-8a29-1d0bb1317339','Uğur Yıldız','TICARI','TAMAMLANDI','2026-04-30','Uğur YILDIZ','Şirket sahibi Orhan bey ve Cemal bey ile görüşüldü firma Ankara OSTİM''de yaklaşık 25 yıldır vinç işletmeciliği yapıyor Flo''da toplam altı adet mobil vinç 20 adet kamyon üstü  hiyap diye adlandırdıkları vinç mevcut 16.00 R 25 vinç lastiği 315 80 R 22.5 kamyon lastik alımları yapıyor firma ile daha önce Maxam Marc''a lastik Ticaretimiz oldu dayton Marc''a kamyon lastik Ticaretimiz oldu düzenli ödeme yapan firmalardan bir tanesi lastik ihtiyaçları hakkında bilgi alındı şimdilik herhangi bir ihtiyacın olmadığını fakat fiyat teklifi verdikleri Ankara Polatlı mevkiinde bir projenin olduğunu eğer ki bu vermiş oldukları fiyat teklifi karşısında işi alma durumunda bir ihtiyaç olabileceğini olduğu taktirde de tarafımızdan irtibata geçip mutlaka bir fiyat teklifi alacaklarini söyledi Orhan bey','{}'::jsonb,'EXCEL_MIGRASYON','44ec101f-9797-407c-8a29-1d0bb1317339') ON CONFLICT (id) DO NOTHING;
