INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('72b639f3-11e1-538d-a880-f841bf9df5e8','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='PARMETA LOJISTIK' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'963b4b24-8169-524b-9789-4bf6b99ff7b4'::uuid),'44ec101f-9797-407c-8a29-1d0bb1317339','Uğur Yıldız','TICARI','TAMAMLANDI','2026-05-07','Uğur YILDIZ','Satınalma sorumlusu Selim Bey''le Ankara merkez ofislerinde görüşüldü bu firma aynı zamanda Mavi Beyaz akaryakıt Demsa akaryakıt ve Parmeta Lojistik mavi Beyaz lojistik isminde grup şirketleri de var yaklaşık altı yıldır ticaret yapmaktayız Selim beyle genel bir görüşmeyle sohbete başladım firma Türkiye genelinde altı adet Opet benzin istasyonu var aynı zamanda opetin Türkiye''nin geniş bir bölgesinde akaryakıt nakliye işini yapıyor bunun yanı sıra toptan akaryakıt satışı yapıyor inşaat firmaları nakliye şirketleri gibi yerlere 2025 yılı altıncı aydan sonra işlerin ciddi bir şekilde azaldığını ve bu 2026 yılında bu azalmanın daha çok hissedildiğiini her iki yılda bir filolarında bulunan çekici ve Dorseleri yenilediklerini fakat bu son 2 3 yıldır bunu yapamadıklarını şu anda filo''da en yeni aracın çekici ve Dorse olarak 2023 model olduğunu bugün bir Mercedes çekici 8 milyon TL bunun Dorse esi ise 4 milyon TL olduğunu yani bir araç takım halinde 12 milyon TL''ye geldiğini fakat bu yatırım karşılığında bunu amorti edecek bir işin olmadığını toptan akaryakıt satışı yapmış oldukları filolardan özellikle inşaat firmalarından ödemelerini olması gereken vadelerde yapamadıklarını tahsilatların özellikle 2026 yılı başından itibaren çok kötü gittiğini söyledi artık eskisi gibi toplu lastik alımından ise ihtiyaca göre lastik alımlarının yapılması için şirketin bir karar aldığını söyledi herhangi bir ihtiyaç durumunda sürekli iletişim halinde olduğumuzu ve fiyat aldığını söyledi Selim bey','{}'::jsonb,'EXCEL_MIGRASYON','44ec101f-9797-407c-8a29-1d0bb1317339') ON CONFLICT (id) DO NOTHING;
