INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d1af2bd9-b564-5ae3-9be3-8cd1fc9d3d2f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BAMTAŞ İNŞAAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'0f946bf2-f071-5cfb-babb-09d5c0129d74'::uuid),'44ec101f-9797-407c-8a29-1d0bb1317339','Uğur Yıldız','TICARI','TAMAMLANDI','2026-07-09','Uğur YILDIZ','Satın alma sorumlusu utku bey ve zeki bey ile görüşüldü Sinop boyabat şantiyesi ve Çanakkale çan şantiyesi için toplam 100 adet 13 r 22.5 Maden çeker 65 adet 385 65 r 22.5 Hafriyat pilot için fiyat teklifi istendi teklif verildi vermiş olduğumuz fiyat teklifinde L317 600d ve m-trailer İçin fiyat istenmişti almış oldukları fiyat teklifleri üzerinde değerlendirmeler yapıldı tarafımıza yapılan dönüş sadece m-tailer için oldu L317 ve tQ01 Arasındaki fiyat farkının 2045 tl+ kdv olduğunu GO2 PRO ve m- trailer Arasındaki fiyat farkının 915 tl oldu burada pilotta ki fark kabul edilebilir bir fark fakat diğer lastik ekteki 2045 tl farkın Kabul edilebilir olmadığını söylediler sonrasında 600 d için 21.000 TL KDV dahil öncesinde bu fiyata lassa 600d yi  iki üç araç kadar verebileceğimizi sonrasında da istemiş oldukları adetin tamamını verebileceğimizi söyledim Kendi içlerinde değerlendirme yaptıktan sonra ihtiyaçları olan 13 r 22.5 içinde lassa 600d kararı verildi 7 adet 900x22.5 megaherkül jant 7 adet 11.75x22.5 kanpana jantlarda jantaş maxıon olarak almış oldukları Fiyattan verildi sipariş alındı toplam 165 adet lastik 14 adet cant olarak sevkiyatı planlanıyor','{}'::jsonb,'EXCEL_MIGRASYON','44ec101f-9797-407c-8a29-1d0bb1317339') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('99912994-40f1-53ad-b8e6-d478ed28932f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='OĞUZHAN ULUSLARARASI NAKLİYAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'cea515f7-c6f7-5413-91cc-885e8718a47d'::uuid),'44ec101f-9797-407c-8a29-1d0bb1317339','Uğur Yıldız','TICARI','TAMAMLANDI','2026-07-09','Uğur YILDIZ','Şirket sahipleri bedirhan bey Oğuzhan bey Oktay bey irem Ankara merkez ofislerinde toplantı yapıldı bakiyeleri olan 1.585.000 tl karşılığında 1.600.000 tl çek alındı ihtiyaçları olan100 adet  315 70 r 22,5 Çeker 40 adet 315 70 TL 22,5 düz tip lastik için lassa marka üzerinde kendileriyle görüşme yapıldı fakat firma bu aralar kendi çekini kullanmak istemediğinden dolayı 90 gün vade yapabileceğimizi bunun için biri sağ tarafından destek isteyip sonrasında fiyat verebileceğimizi söyledim almış oldukları müşteri çekleri muhasebeden getirilip bakıldı vadeleri çok yüksek olduğundan dolayı 6 ay 7 ay 8 ay çek karşılığında müşteri çeki karşılığında lastik almayı planladıklarını bu vadede bir ticaretin tarafımızdan olmayacağını söyledi firma yetkilileri bu şekilde çekleri kabul etmeyin diye çeki alanlara sezdenişte bulundu Olması gereken vadeder çek ayarlayıp tekrardan alım konusunu görüşeceklerini söyledi','{}'::jsonb,'EXCEL_MIGRASYON','44ec101f-9797-407c-8a29-1d0bb1317339') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ab789194-092b-5356-88bd-1d128e33b22c','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZAKÇA ORMAN ÜRÜNLERİ' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'a515710d-cbc4-5d13-a52d-09fc8f20647e'::uuid),'44ec101f-9797-407c-8a29-1d0bb1317339','Uğur Yıldız','TICARI','TAMAMLANDI','2026-07-09','Uğur YILDIZ','Şirket sahibi ismail bey ile görüşüldü Bartın ovacuma da orman tomruk nakliyesinde çalışan araçları için 12 adet 385 65 r 22.5 M-trailer İçin fiyat istedi bir islam Memduh dan %8 destek alındı sonrasında firmaya 30 gün içerisinde kredi kartı ödeme modeli ile %36 iskonto yapılarak fiyat verildi 22.985 tl kdv dahil fiyat verildi Aynı las diye özellikle üretim tarihini de sordum 2026 yılına ait üretim tarihli birebir aynı lastiğe 19.000 TLKDV dahil fiyat geldiğini söyledi dedim bu işte farklı bir durum var %47 ıskonto ya geliyor lastik 5 Haziran listesinde o kadar kesin spariş alacağım gözüyle baktığım talep bir başka firmaya gitti özellikle ismail beye kim bu firma bayi mi değil mi diye sorduğumda zaten elinde 16 adet olduğunu bu fiyata da bir yerden alamayacağını söyledi dedi satan firma  Devrek''te bir lastik firması olduğunu söyledi','{}'::jsonb,'EXCEL_MIGRASYON','44ec101f-9797-407c-8a29-1d0bb1317339') ON CONFLICT (id) DO NOTHING;
