INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1fe33cd9-770e-5519-8883-1fb82d6296f4','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YILNAK AĞIR NAKLİYAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'cd211a5b-4732-527f-8b9e-bb0f0a28c9e7'::uuid),'44ec101f-9797-407c-8a29-1d0bb1317339','Uğur Yıldız','TICARI','TAMAMLANDI','2026-07-15','Uğur YILDIZ','Kademe ve garaj sorumlusu Yücel bey ve Vahit bey ile görüşüldü Filoda toplam 8 adet Çift çeker çekici 10 adet  lowbet Treyler mevcut fakat yaklaşık 4 5 Aydır işlerinin çok durgun olduğunu özellikle navlun fiyatlarının zarar seviyesinde olduğundan dolayı gelen işe de gitmediklerini çok nadir araçların nakliyeye çıktığını şu an için herhangi bir lastik ihtiyaçlarının olmadığını daha önce almış oldukları goodyear marka lastiklerden 315 80 r 22.5 ve 245 70 r 17.5 Stoklarında lastik olduğunu işlerin hareketlenmesi durumunda lastik ihtiyacı olduğunda tarafımız ile iletişime geçip fiyat teklifi alacaklarını söylediler','{}'::jsonb,'EXCEL_MIGRASYON','44ec101f-9797-407c-8a29-1d0bb1317339') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('152d2dfb-958c-5024-803e-9969e7aff228','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='CEYLAN TREYLER' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'18fee4f5-8bd2-5f4b-aa27-4bdd4c533d52'::uuid),'44ec101f-9797-407c-8a29-1d0bb1317339','Uğur Yıldız','TICARI','TAMAMLANDI','2026-07-15','Uğur YILDIZ','Şirket sahibi Fahrettin bey ve kızı Sibel hanım ile Ankara merkez ofislerinde görüşüldü firma yaklaşık 40 yıldır Ankara ostim ve saray köyü tesislerinde dorse imalatı işi ile uğraşıyor Son 10 yılın en kötü yılını yaşamakta olduklarını söyledi özellikle işlerin ciddi anlamda düştüğünü olan işlerin ise ödemelerinin vadelerinin çok yükseldiğini karşılıklarının çok düştüğünü söyledi ellerinde sadece bir firmaya ait 8 adet lovbet Dosya imalatının olduğunu bunun için ise 245 70 r 17,5 petlas marka lastik ve cant alındığını bu alımın ise yaklaşık 4 ay önce gerçekleştiğini can lastik set halinde 9000 TLKDV dahil ile Abdulkadir Özcan firmasından alındığını söyledi 120 gün çek ödeme olarak alım yaptıklarını bu projenin haricinde herhangi bir işin olmadığını olduğu takdirde ise tarafımızdan bu ölçüye istinaden lastik ve jant  fiyatı alacaklarını söyledi','{}'::jsonb,'EXCEL_MIGRASYON','44ec101f-9797-407c-8a29-1d0bb1317339') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('94b46c47-0814-5540-808e-7bec23b20baf','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZDEMİRSAN TREYLER' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'f3f54a2a-ee07-505b-81bc-0a4922d4853f'::uuid),'44ec101f-9797-407c-8a29-1d0bb1317339','Uğur Yıldız','TICARI','TAMAMLANDI','2026-07-15','Uğur YILDIZ','Şirket sahibi ibrahim bey ile Ankara merkez ofislerinde görüşüldü Bu firmadaGelen siparişe göre genelde lowbet dorse imalatı yapmakta olan ankara''nın çok eski firmalarından şirket sahibi ibrahim bey siparişlerin gelen taleplerin eskiye nazaran çok düşük olduğunu özellikle iş yaptıkları müşterilerden gelen ödemelerin 2025 yılı Şubat ayından itibaren çok kötü olduğunu vadelerin ortalamada 7 ay 8 ay gibi sürelere dayandığını söyledi lastik ihtiyaç durumlarında daha önceki üretimlerimiz de en çok satın almış olduğumuz lassa pirelli goodyear markaları artık yerini Biraz daha ucuz markalara özellikle de petlas marka son 5 6 aydır Biraz daha fazla tercih edilen bir marka olmaya başladığını söyledi gerek maliyetten dolayı hesaplı olmasından ve özellikle Abdulkadir Özcan tarafından kendilerini artık üretimimiz eskiye nazaran çok değişti lastiğin kalitesini arttırdık söylemleri ile pazara girdiklerini söyledi şu an için herhangi bir lastik ihtiyacının olmadığını olduğu takdirde ağırlıkla lastik ölçüsünde 245 70 r 17.5 treyler lastiği alımı yaptıklarını İhtiyaç durumunda lassa için fiyat alacağını söyledi','{}'::jsonb,'EXCEL_MIGRASYON','44ec101f-9797-407c-8a29-1d0bb1317339') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('fb90ef16-a77a-515a-ad17-449c1f255895','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ALTINORDU DORSE' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'7e8e8928-e8cd-5431-a06f-15bcb05c8dd1'::uuid),'44ec101f-9797-407c-8a29-1d0bb1317339','Uğur Yıldız','TICARI','TAMAMLANDI','2026-07-15','Uğur YILDIZ','Satın alma Müdürü Hasan bey ile Ankara merkez ofislerinde görüşüldü firma dosya imalatı yapmakta olup gelen siparişler doğrultusunda lastik ve aynı zamanda setli vaziyette lastik jant alımı yapıyor Bu firma daha önceki ziyaretlerimde ağırlıkla lassa marka lastik alımlarını kardeşler ulaşımdan lastik ve jant Olarak setli yaptığını pirelli markayı ise Yaşar oto lastikten alım yaptığını aynı şekilde set halinde şimdi ise yaklaşık 6 7 Aydır petlas marka olarak tedarik ettiklerini söyledi nedenini sorduğumda ise biz burada dosya imalatı yaparken bütün maliyetleri hesaplayarak müşterilerimize fiyat verdiklerini lastik ve jantı Maliyet hesaplarken artık lassa pirelli goodyear fiyatları ile petlas marka fiyatın arasında ciddi oranlar teşkil etmekte olduğu için Müşterilerine de bu markalar olursa fiyatın bu şekilde olacağını petlas marka olursa fiyatın buraya inebileceğini söylediğimizde den dolayı tercih edildiğini söyledi ama yine de ısrarla lassa pirelli goodyear marka lastikleri tercih edenler olduğunu bu gibi durumlarda ihtiyaç durumunda lassa olarak fiyat alacağını söyledi Hasan bey','{}'::jsonb,'EXCEL_MIGRASYON','44ec101f-9797-407c-8a29-1d0bb1317339') ON CONFLICT (id) DO NOTHING;
